<script setup>
import { computed,onMounted,ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { api } from '../api.js'
import PlayerAvatar from '../components/PlayerAvatar.vue'
import { useConfirmationStore } from '../stores/confirmation.js'
import { useInputDialogStore } from '../stores/input-dialog.js'
import { formatInteger } from '../utils/format.js'
const route=useRoute(),router=useRouter(),confirmation=useConfirmationStore(),inputDialog=useInputDialogStore()
const data=ref({group:null,players:[],squads:[],can_edit:false}),loading=ref(true),busy=ref(false),error=ref('')
const labels={melee:'Милик',archer:'Лучник',mage:'Маг',healer:'Хил',bard:'Бард',tank:'Танк'}
const byId=computed(()=>new Map(data.value.players.map(p=>[p.id,p])))
const players=s=>s.player_ids.map(id=>byId.value.get(id)).filter(Boolean)
const assigned=computed(()=>new Set(data.value.squads.flatMap(s=>s.player_ids)))
const unassigned=computed(()=>data.value.players.filter(p=>!assigned.value.has(p.id)))
async function load(){loading.value=true;try{data.value=(await api.get(`/api/groups/${route.params.id}/squads`)).data}catch(e){if(e.response?.status===403)router.replace('/forbidden');else error.value=e.response?.data?.message??'Не удалось загрузить состав.'}finally{loading.value=false}}
async function createSquad(){busy.value=true;try{await api.post(`/api/groups/${route.params.id}/squads`,{});await load()}finally{busy.value=false}}
async function rename(s){const value=await inputDialog.ask({title:'Переименовать группу',label:'Название',initialValue:s.name,maxLength:120,confirmLabel:'Переименовать'});if(value?.trim())await api.patch(`/api/groups/${route.params.id}/squads/${s.id}`,{name:value.trim()});await load()}
async function remove(s){if(!await confirmation.ask({title:'Удалить группу?',message:`Игроки из «${s.name}» останутся в КП без распределения.`,confirmLabel:'Удалить',danger:true}))return;await api.delete(`/api/groups/${route.params.id}/squads/${s.id}`);await load()}
async function assign(player,id){busy.value=true;try{if(id)await api.put(`/api/groups/${route.params.id}/squads/${id}/players`,{player_id:player.id});else await api.delete(`/api/groups/${route.params.id}/squads/players/${player.id}`);await load()}finally{busy.value=false}}
const current=id=>data.value.squads.find(s=>s.player_ids.includes(id))?.id??''
onMounted(load)
</script>
<template><section class="party-squads-page"><div class="page-heading squads-heading"><div><p class="eyebrow">КОНСТ-ПАТИ · СОСТАВ</p><h1>{{ data.group?.name??'Пятёрки' }}</h1><p>Распределите участников по 5 человек.</p></div><button v-if="data.can_edit" class="primary" :disabled="busy" @click="createSquad">+ Добавить группу</button></div><p v-if="error" class="notice error">{{ error }}</p><div v-if="loading" class="panel squads-loading">Загружаем состав…</div><template v-else><div class="squads-grid"><article v-for="(squad,index) in data.squads" :key="squad.id" class="panel squad-card"><header><div><span>ГРУППА {{ String(index+1).padStart(2,'0') }}</span><h2>{{ squad.name }}</h2></div><b :class="{full:squad.player_ids.length===5}">{{ squad.player_ids.length }} / 5</b></header><div class="squad-list"><div v-for="player in players(squad)" :key="player.id" :class="['squad-player',{readonly:!data.can_edit}]"><PlayerAvatar :player="player" size="small"/><RouterLink :to="`/players/${player.id}`"><strong>{{ player.nickname }} <img v-if="player.has_ship" class="ship-mark" src="/images/profile-assets/ship-badge.png" alt="Есть корабль" title="Есть корабль"></strong><small>ГС {{ formatInteger(player.gear_score||0) }} · {{ player.attendance_percentage }}%</small></RouterLink><span :class="['class-tag',`class-${player.class}`]">{{ labels[player.class] }}</span><select v-if="data.can_edit" :value="current(player.id)" :disabled="busy" @change="assign(player,Number($event.target.value)||null)"><option value="">Без группы</option><option v-for="target in data.squads" :key="target.id" :value="target.id" :disabled="target.player_ids.length>=5&&target.id!==squad.id">{{ target.name }}</option></select></div><div v-for="slot in 5-squad.player_ids.length" :key="slot" class="squad-empty-slot"><span>+</span> Свободное место</div></div><footer v-if="data.can_edit"><button @click="rename(squad)">Переименовать</button><button class="danger" @click="remove(squad)">Удалить</button></footer></article></div><section class="panel unassigned-panel"><div class="panel-title"><div><h2>Без группы</h2><p>{{ unassigned.length?'Участники, которых ещё нужно распределить':'Все участники распределены' }}</p></div><b>{{ unassigned.length }}</b></div><div class="unassigned-list"><div v-for="player in unassigned" :key="player.id" :class="['squad-player',{readonly:!data.can_edit}]"><PlayerAvatar :player="player" size="small"/><RouterLink :to="`/players/${player.id}`"><strong>{{ player.nickname }} <img v-if="player.has_ship" class="ship-mark" src="/images/profile-assets/ship-badge.png" alt="Есть корабль" title="Есть корабль"></strong><small>ГС {{ formatInteger(player.gear_score||0) }} · {{ player.attendance_percentage }}%</small></RouterLink><span :class="['class-tag',`class-${player.class}`]">{{ labels[player.class] }}</span><select v-if="data.can_edit" value="" @change="assign(player,Number($event.target.value)||null)"><option value="">Выбрать группу</option><option v-for="target in data.squads" :key="target.id" :value="target.id">{{ target.name }}</option></select></div></div></section></template></section></template>
